<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ثبت‌نام ورزشکار</title><style>body{font-family:Tahoma,Arial,sans-serif;background:#0c1421;color:#e9f0fb;margin:0;padding:24px}main{max-width:460px;margin:7vh auto;background:#172438;padding:28px;border-radius:18px}label{display:block;margin-top:14px}input,button{box-sizing:border-box;width:100%;padding:12px;border-radius:9px;font:inherit}input{background:#0b1728;color:white;border:1px solid #42526b;margin-top:7px}button{margin-top:20px;background:#70d6b2;border:0;color:#08241b;cursor:pointer;font-weight:bold}button:disabled{opacity:.6}#status{min-height:2em;line-height:1.8}a{color:#9be7d0}</style><link rel="stylesheet" href="/assets/fitness-portals.css"></head><body><main><h1>ثبت‌نام ورزشکار</h1><p>شماره موبایل خود را تأیید کنید و سپس حساب بسازید.</p><form id="request"><label>شماره موبایل<input name="phone" autocomplete="tel" inputmode="tel" placeholder="09123456789" required></label><button>دریافت کد تأیید</button></form><form id="register" hidden><label>نام و نام خانوادگی<input name="name" maxlength="120" autocomplete="name" required></label><label>کد شش‌رقمی<input name="code" inputmode="numeric" pattern="[0-9]{6}" required></label><label>رمز عبور (حداقل ۱۰ کاراکتر)<input name="password" type="password" minlength="10" autocomplete="new-password" required></label><label>تکرار رمز عبور<input name="password_confirmation" type="password" minlength="10" autocomplete="new-password" required></label><button>ایجاد حساب</button></form><p id="status" role="status" aria-live="polite"></p><a href="/athlete">ورود ورزشکار</a></main><script>const requestForm=document.getElementById('request'),registerForm=document.getElementById('register'),status=document.getElementById('status');let phone='';async function send(url,data,form){const btn=form.querySelector('button');btn.disabled=true;status.textContent='در حال پردازش…';try{const response=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||result.message||'درخواست ناموفق بود');return result}catch(e){status.textContent=e.message;return null}finally{btn.disabled=false}}requestForm.addEventListener('submit',async e=>{e.preventDefault();phone=new FormData(requestForm).get('phone').trim();const result=await send('/api/v1/athlete/otp/request',{phone},requestForm);if(result){registerForm.hidden=false;status.textContent='کد تأیید درخواست شد. کد را وارد کنید.'}});registerForm.addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(registerForm));const result=await send('/api/v1/athlete/register',{...data,phone},registerForm);if(result){status.textContent='حساب ایجاد شد و وارد شدید. می‌توانید خرید را ادامه دهید.';registerForm.hidden=true;setTimeout(()=>{location.assign('/checkout')},700)}})</script></body></html>